import { Command } from 'commander';
import { clearHistory, computeStats, loadHistory } from '../utils/history.js';

export function registerHistory(program: Command) {
  const history = program.command('history').description('Command history analytics');

  history
    .command('stats')
    .description('Show usage frequency and session length')
    .action(() => {
      const stats = computeStats();
      console.log('Total commands:', stats.total);
      console.log('Most used:', stats.mostUsed.join(', '));
      console.log('Average session length (ms):', Math.round(stats.averageSessionLength));
      console.log('Recent:');
      stats.recent.forEach(r => console.log(`- ${new Date(r.timestamp).toISOString()} ${r.command} (${r.durationMs}ms)`));
    });

  history
    .command('list')
    .description('Show recent command history')
    .action(() => {
      loadHistory().slice(-20).forEach(r => console.log(`${new Date(r.timestamp).toLocaleString()} - ${r.command}`));
    });

  history
    .command('clear')
    .description('Clear history store')
    .action(() => clearHistory());
}
